import { describe, expect, it } from "vitest";
import { LONG_PARAGRAPH, shapeProse, splitSentences } from "@/lib/prose";

/** The note that prompted the reflow, verbatim from T113 on 2026-08-22. */
const LEDGER =
  "State on 2026-08-22: data/2026/expenses.yaml generated by sync_expenses — 143 items, " +
  "$4,347.60 non-broker expenses (+ $3,390 broker fees in deals.yaml) → Schedule C net " +
  "$3,562.40. Receipts harvested from email (scripts/harvest_receipts.py) cover 104/143 " +
  "items, $3,258 (75%). Remaining gaps are vendors that don't email receipts: GA SOS annual " +
  "registration ($220, ecorp.sos.ga.gov), ChatGPT Plus ($20/mo — OpenAI billing portal), " +
  "Squarespace domains/workspaces (~$435 Jan–May; Squarespace → Billing → Invoices), Apple " +
  "Developer Program ($99, developer.apple.com), Spotify ($12.99/mo, account page).";

describe("splitSentences", () => {
  it("splits at terminal punctuation followed by a capital or digit", () => {
    expect(splitSentences("One thing. Another thing! A third? 4 more.")).toEqual([
      "One thing.",
      "Another thing!",
      "A third?",
      "4 more.",
    ]);
  });

  it("does not split decimals, domains, paths or lower-case continuations", () => {
    expect(
      splitSentences("Net $3,562.40 from ecorp.sos.ga.gov via scripts/x.py. it worked.")
    ).toEqual(["Net $3,562.40 from ecorp.sos.ga.gov via scripts/x.py. it worked."]);
  });

  it("does not split after common abbreviations or initials", () => {
    expect(splitSentences("Use e.g. Stripe vs. Square. Ask Dr. Smith or J. Doe. Done.")).toEqual(
      ["Use e.g. Stripe vs. Square.", "Ask Dr. Smith or J. Doe.", "Done."]
    );
  });

  it("keeps a closing quote or bracket with its sentence", () => {
    expect(splitSentences('He said "no." Then left (quietly.) Fin.')).toEqual([
      'He said "no."',
      "Then left (quietly.)",
      "Fin.",
    ]);
  });
});

describe("shapeProse", () => {
  it("breaks a long single-line paragraph into readable paragraphs", () => {
    const shaped = shapeProse(LEDGER);
    const paras = shaped.split("\n\n");
    expect(paras.length).toBeGreaterThan(1);
    // Nothing is lost or reordered: joining the paragraphs back gives the
    // original text, whitespace aside.
    expect(paras.join(" ")).toBe(LEDGER);
    // Every paragraph starts on a sentence.
    for (const p of paras) expect(p).toMatch(/^[A-Z0-9$"(]/);
    // The first split lands after the Schedule C figure, not inside it.
    expect(paras[0]).toMatch(/\$3,562\.40\.$/);
  });

  it("leaves a short paragraph exactly as written", () => {
    const short = "Two sentences. That is all.";
    expect(shapeProse(short)).toBe(short);
  });

  it("leaves a paragraph the author already broke into lines alone", () => {
    const line = "A sentence that is long enough to matter. ".repeat(12).trim();
    const src = `${line}\nsecond line`;
    expect(src.length).toBeGreaterThan(LONG_PARAGRAPH);
    expect(shapeProse(src)).toBe(src);
  });

  it("leaves structure alone: fences, lists, tables, headings, html", () => {
    const long = "Sentence number one is here. ".repeat(20).trim();
    const src = [
      "# Heading " + long,
      "",
      "- " + long,
      "",
      "| a | b |",
      "| - | - |",
      `| ${long} | x |`,
      "",
      "```",
      long,
      "",
      long,
      "```",
      "",
      `<div>${long}</div>`,
      "",
      "> " + long,
    ].join("\n");
    expect(shapeProse(src)).toBe(src);
  });

  it("reflows only the paragraphs that need it inside a mixed document", () => {
    const long = "Sentence number one is here. ".repeat(20).trim();
    const src = ["## Title", "", long, "", "- item", "", "short one."].join("\n");
    const shaped = shapeProse(src);
    expect(shaped.startsWith("## Title\n\n")).toBe(true);
    expect(shaped.endsWith("\n\n- item\n\nshort one.")).toBe(true);
    expect(shaped.split("\n\n").length).toBeGreaterThan(4);
  });

  it("does not split a long paragraph that is a single sentence", () => {
    const one = "word ".repeat(100).trim() + ".";
    expect(shapeProse(one)).toBe(one);
  });
});
